export type VizMode = 'sales' | 'monitoring';

/** [timestamp in ms, value]. `null` value = gap in the series. */
export type TimePoint = readonly [timestamp: number, value: number | null];

export interface TimeSeries {
  id: string;
  name: string;
  points: readonly TimePoint[];
}

export interface SalesMonitoringWidgetProps {
  /** Per-mode data. Both modes share one data shape, the widget adapts it to the right engine. */
  series: Record<VizMode, readonly TimeSeries[]>;
  /** Controlled mode. */
  mode?: VizMode;
  /** Initial mode when uncontrolled. Defaults to `sales`. */
  defaultMode?: VizMode;
  onModeChange?: (mode: VizMode) => void;
  /** Chart height in px. ChartKit fills its parent, so the height must be explicit. */
  height?: number;
  /** Optional Y axis title per mode. */
  yAxisTitle?: Partial<Record<VizMode, string>>;
}
EOF
cat > adapters.ts <<'EOF'
import type {ChartKitProps} from '@gravity-ui/chartkit';

import type {TimeSeries} from './types';

type SalesData = ChartKitProps<'gravity-charts'>['data'];
type MonitoringData = ChartKitProps<'yagr'>['data'];

/** Regular line chart (gravity-charts): one `{x, y}` point list per series. */
export function toSalesChartData(series: readonly TimeSeries[], yTitle?: string): SalesData {
  return {
    series: {
      data: series.map((s) => ({
        type: 'line' as const,
        name: s.name,
        data: s.points.map(([x, y]) => ({x, y})),
      })),
    },
    xAxis: {type: 'datetime'},
    yAxis: [{title: yTitle ? {text: yTitle} : undefined}],
  };
}

/**
 * Dense time series (yagr): one shared, sorted timeline + value arrays aligned to it.
 * Series with different timestamps are merged onto the union timeline, missing points are `null`.
 */
export function toMonitoringData(series: readonly TimeSeries[], yTitle?: string): MonitoringData {
  const stamps = new Set<number>();
  for (const s of series) {
    for (const [t] of s.points) {
      stamps.add(t);
    }
  }
  const timeline = Array.from(stamps).sort((a, b) => a - b);

  const graphs = series.map((s) => {
    const byTime = new Map<number, number | null>(s.points);
    return {
      id: s.id,
      name: s.name,
      data: timeline.map((t) => byTime.get(t) ?? null),
    };
  });

  return {
    data: {graphs, timeline},
    libraryConfig: {
      chart: {series: {type: 'line'}},
      axes: yTitle ? {y: {label: yTitle}} : undefined,
    },
  };
}
EOF
cat > plugins.ts <<'EOF'
import {settings} from '@gravity-ui/chartkit';
import type {ChartKitPlugin} from '@gravity-ui/chartkit';

import type {VizMode} from './types';

/**
 * Each engine lives behind a dynamic import, so neither the plugin module nor the
 * charting library it pulls in (@gravity-ui/charts / @gravity-ui/yagr) is in the main bundle.
 * The module is requested only when its mode is first shown.
 */
const importers: Record<VizMode, () => Promise<ChartKitPlugin>> = {
  sales: () => import('@gravity-ui/chartkit/gravity-charts').then((m) => m.GravityChartsPlugin),
  monitoring: () => import('@gravity-ui/chartkit/yagr').then((m) => m.YagrPlugin),
};

const registrations = new Map<VizMode, Promise<void>>();

export function registerEngine(mode: VizMode): Promise<void> {
  let promise = registrations.get(mode);
  if (!promise) {
    promise = importers[mode]().then((plugin) => {
      settings.set({plugins: [plugin]});
    });
    // allow a retry after a network failure
    promise.catch(() => registrations.delete(mode));
    registrations.set(mode, promise);
  }
  return promise;
}
EOF
cat > SalesMonitoringWidget.tsx <<'EOF'
import React from 'react';
import ChartKit from '@gravity-ui/chartkit';
import {Alert, Button, Card, Flex, Loader, SegmentedRadioGroup, Text} from '@gravity-ui/uikit';

import {toMonitoringData, toSalesChartData} from './adapters';
import {registerEngine} from './plugins';
import type {SalesMonitoringWidgetProps, VizMode} from './types';

const MODE_OPTIONS = [
  {value: 'sales', content: 'Продажи'},
  {value: 'monitoring', content: 'Мониторинг'},
] satisfies {value: VizMode; content: string}[];

const TITLES: Record<VizMode, string> = {
  sales: 'Динамика продаж',
  monitoring: 'Мониторинг',
};

function CenteredLoader() {
  return (
    <Flex alignItems="center" justifyContent="center" style={{height: '100%'}}>
      <Loader size="m" />
    </Flex>
  );
}

type EngineState = {mode: VizMode; status: 'loading' | 'ready' | 'error'};

/** Loads the ChartKit plugin of the current mode on demand. */
function useEngine(mode: VizMode) {
  const [attempt, setAttempt] = React.useState(0);
  const [state, setState] = React.useState<EngineState>({mode, status: 'loading'});

  React.useEffect(() => {
    let cancelled = false;
    setState({mode, status: 'loading'});
    registerEngine(mode).then(
      () => !cancelled && setState({mode, status: 'ready'}),
      () => !cancelled && setState({mode, status: 'error'}),
    );
    return () => {
      cancelled = true;
    };
  }, [mode, attempt]);

  // never report "ready" for a mode other than the requested one
  const status = state.mode === mode ? state.status : 'loading';
  const retry = React.useCallback(() => setAttempt((n) => n + 1), []);
  return {status, retry};
}

export function SalesMonitoringWidget({
  series,
  mode: controlledMode,
  defaultMode = 'sales',
  onModeChange,
  height = 360,
  yAxisTitle,
}: SalesMonitoringWidgetProps) {
  const [innerMode, setInnerMode] = React.useState<VizMode>(defaultMode);
  const mode = controlledMode ?? innerMode;

  const handleModeChange = React.useCallback(
    (next: VizMode) => {
      if (controlledMode === undefined) {
        setInnerMode(next);
      }
      onModeChange?.(next);
    },
    [controlledMode, onModeChange],
  );

  const {status, retry} = useEngine(mode);

  const salesData = React.useMemo(
    () => toSalesChartData(series.sales, yAxisTitle?.sales),
    [series.sales, yAxisTitle?.sales],
  );
  const monitoringData = React.useMemo(
    () => toMonitoringData(series.monitoring, yAxisTitle?.monitoring),
    [series.monitoring, yAxisTitle?.monitoring],
  );

  const renderChart = () => {
    if (status === 'error') {
      return (
        <Alert
          theme="danger"
          title="Не удалось загрузить график"
          actions={<Button onClick={retry}>Повторить</Button>}
        />
      );
    }
    if (status === 'loading') {
      return <CenteredLoader />;
    }
    const common = {
      renderPluginLoader: () => <CenteredLoader />,
      renderError: ({message, resetError}: {message: string; resetError: () => void}) => (
        <Alert
          theme="danger"
          title="Ошибка отрисовки графика"
          message={message}
          actions={<Button onClick={resetError}>Повторить</Button>}
        />
      ),
    };
    return mode === 'sales' ? (
      <ChartKit key="sales" type="gravity-charts" data={salesData} {...common} />
    ) : (
      <ChartKit key="monitoring" type="yagr" data={monitoringData} {...common} />
    );
  };

  return (
    <Card view="outlined" type="container" style={{padding: 'var(--g-spacing-4)'}}>
      <Flex direction="column" gap={4}>
        <Flex alignItems="center" justifyContent="space-between" gap={3} wrap>
          <Text variant="header-1" style={{minWidth: 0}}>
            {TITLES[mode]}
          </Text>
          <SegmentedRadioGroup
            aria-label="Режим графика"
            value={mode}
            onUpdate={handleModeChange}
            options={MODE_OPTIONS}
          />
        </Flex>
        <div style={{height, minWidth: 0}}>{renderChart()}</div>
      </Flex>
    </Card>
  );
